CREATE TABLE work_jobs(id VARCHAR(40) PRIMARY KEY,incident_id VARCHAR(40) NOT NULL REFERENCES incidents(id),phase VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,token VARCHAR(40),lease_until TIMESTAMP,available_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL,error TEXT,UNIQUE(incident_id,phase,created_at));
CREATE INDEX work_ready ON work_jobs(status,available_at,lease_until);
CREATE TABLE work_checkpoints(job_id VARCHAR(40) NOT NULL REFERENCES work_jobs(id),stage VARCHAR(40) NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(job_id,stage));
ALTER TABLE skills ADD COLUMN revision INTEGER NOT NULL DEFAULT 0;
CREATE TABLE skill_revisions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,skill_id VARCHAR(40) NOT NULL REFERENCES skills(id),revision INTEGER NOT NULL,action VARCHAR(30) NOT NULL,actor VARCHAR(60) NOT NULL,reason TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL,UNIQUE(skill_id,revision));
CREATE TABLE notifications(id VARCHAR(40) PRIMARY KEY,incident_id VARCHAR(40) NOT NULL REFERENCES incidents(id),kind VARCHAR(30) NOT NULL,dedupe_key VARCHAR(120) NOT NULL UNIQUE,message TEXT NOT NULL,channel VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP NOT NULL,acknowledged_at TIMESTAMP,acknowledged_by VARCHAR(60));
CREATE TABLE evaluation_cases(id VARCHAR(40) PRIMARY KEY,dataset_version VARCHAR(40) NOT NULL,category VARCHAR(40) NOT NULL,raw_message TEXT,observations TEXT NOT NULL,expected_type VARCHAR(30),expected_severity VARCHAR(10),expected_department VARCHAR(40),expected_recurrence BOOLEAN,expected_review BOOLEAN NOT NULL,expected_eligible BOOLEAN NOT NULL,rationale TEXT NOT NULL);
INSERT INTO work_jobs(id,incident_id,phase,status,available_at,created_at) SELECT id,id,CASE WHEN status='RECOVERING' THEN 'RECOVER' WHEN status='ANALYZING' AND decision_json IS NOT NULL THEN 'CONTINUE' ELSE 'ANALYZE' END,'QUEUED',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM incidents WHERE deleted_at IS NULL AND status IN ('REGISTERED','ANALYZING','RECOVERING');

ALTER TABLE incidents ADD COLUMN phase_started_at TIMESTAMP;
ALTER TABLE incidents ADD COLUMN first_response_at TIMESTAMP;
UPDATE incidents SET phase_started_at=created_at;
ALTER TABLE incidents ALTER COLUMN phase_started_at SET DEFAULT CURRENT_TIMESTAMP;

ALTER TABLE notifications ADD COLUMN attempts INTEGER NOT NULL DEFAULT 0;
CREATE TABLE notification_deliveries(notification_id VARCHAR(40) PRIMARY KEY REFERENCES notifications(id),payload_json TEXT NOT NULL,received_at TIMESTAMP NOT NULL);
